import{_ as n}from"./chunks/performance-trends.BEEamWXJ.js";import{_ as d,C as t,o as l,c as h,j as s,a as m,E as a,a6 as o}from"./chunks/framework.CCKCzdWs.js";const T=JSON.parse(`{"title":"Slow tests & wasted time","description":"Where the suite's time goes: duration trends, a run's Timeline of its workers, timeout headroom, stale test.slow() marks, wasted wait and retry time, slow endpoints and Web Vitals.","frontmatter":{"title":"Slow tests & wasted time","description":"Where the suite's time goes: duration trends, a run's Timeline of its workers, timeout headroom, stale test.slow() marks, wasted wait and retry time, slow endpoints and Web Vitals.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/slow-tests.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/slow-tests.html"}],["meta",{"property":"og:title","content":"Slow tests & wasted time | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Where the suite's time goes: duration trends, a run's Timeline of its workers, timeout headroom, stale test.slow() marks, wasted wait and retry time, slow endpoints and Web Vitals."}]]},"headers":[],"relativePath":"features/slow-tests.md","filePath":"features/slow-tests.md","lastUpdated":1795612163000}`),c={name:"features/slow-tests.md"};function u(p,e,w,g,f,k){const r=t("Needs"),i=t("DemoExamples");return l(),h("div",null,[e[0]||(e[0]=s("h1",{id:"slow-tests-wasted-time",tabindex:"-1"},[m("Slow tests & wasted time "),s("a",{class:"header-anchor",href:"#slow-tests-wasted-time","aria-label":'Permalink to "Slow tests & wasted time"'},"​")],-1)),a(r,{reporter:"",fixtures:""}),e[1]||(e[1]=o('<p>The test list tells you what failed; it doesn&#39;t tell you where the <strong>minutes</strong> go. This page covers the project&#39;s <strong>Performance</strong> tab (duration trends, the slowest tests, timeout opportunities, slow endpoints), a run&#39;s <strong>Timeline</strong> and the time Piwi counts as <strong>wasted</strong>. What the run cost the machine is on <a href="./cpu-memory-disk.html">CPU, memory &amp; disk</a>; flaky tests ranked by the time their retries cost, on <a href="./flaky-tests.html#impact-ranking">Flaky tests</a>.</p><h2 id="duration-trends" tabindex="-1">Duration trends <a class="header-anchor" href="#duration-trends" aria-label="Permalink to &quot;Duration trends&quot;">​</a></h2><p>Average and <strong>P90</strong> duration over time, so a few slow outliers don&#39;t hide a real regression (a rising P90 with a flat average is a tail getting worse). Read the percentile, not the average: a handful of slow outliers move it and barely move the mean, and the outliers decide how long a shard takes. <strong>Slowest tests</strong> ranks the top offenders by duration.</p><figure><img src="'+n+'" alt="Performance tab showing the duration trend chart and slowest-tests table"><figcaption>The Performance view — average and P90 duration trends over time, followed by a ranked table of the slowest tests.</figcaption></figure><h2 id="timeout-opportunities" tabindex="-1">Timeout opportunities <a class="header-anchor" href="#timeout-opportunities" aria-label="Permalink to &quot;Timeout opportunities&quot;">​</a></h2><p>Tests whose configured per-test timeout dwarfs their real p95 duration — so a hang or failure waits far longer than it needs to — plus tests still carrying a stale <code>test.slow()</code> mark they no longer need. Each row suggests a tighter timeout (or removing the mark) and the time reclaimable per failing run, ranked by impact.</p><p>An oversized timeout costs nothing while the test passes and its whole budget each time it fails: a thirty-second timeout on a three-second test burns twenty-seven seconds on every failure before anyone learns anything.</p><p>This reads the per-test timeout the <a href="/reference/test-metadata.html#per-test-timeout">reporter captures</a>; runs reported before that shipped still surface stale <code>test.slow()</code> marks from annotations and durations alone. The thresholds are set in <strong>Settings → Performance</strong>.</p><h2 id="wasted-time" tabindex="-1">Wasted time <a class="header-anchor" href="#wasted-time" aria-label="Permalink to &quot;Wasted time&quot;">​</a></h2><p><strong>Wasted time</strong> is time that produced no signal. Piwi counts two kinds:</p><ul><li><strong>Waits</strong>: the time inside wait steps that match the wasted-wait patterns. By default only explicit sleeps count (<code>waitForTimeout</code> and friends), since framework-injected waits (load-state, wait-for-function) are usually unavoidable. Tune the patterns in <strong>Settings → Performance</strong>, or lock them with <a href="/reference/configuration.html#wasted-time"><code>PIWI_WASTED_WAIT_PATTERNS</code></a>; <code>*</code> counts every wait, which shows once how much of the suite is waiting. They are applied when a run is viewed, so a change re-classifies the whole history with no re-run.</li><li><strong>Failed attempts</strong>: the time spent running attempts that ended failed or timed out.</li></ul><p>A run&#39;s test list and an execution&#39;s <strong>Details</strong> popover show each test&#39;s fixed-wait time, and the run&#39;s <strong>Timeline</strong> tab draws the sleeps as bars with <strong>Show waits</strong>. The <strong>Wasted CI time</strong> <a href="./analytics.html">Analytics</a> widget adds waits and failed attempts over time and per project, beside <strong>CI time</strong>, the minutes the runs consumed, and states how much is <strong>reclaimable</strong> by tightening timeouts and dropping stale <code>test.slow()</code> marks. With a <a href="/reference/configuration.html#wasted-time">cost per CI minute</a> set, each wasted-time number carries its cost.</p><p>The flaky list&#39;s <strong>wasted CI minutes</strong> are a narrower number, a test&#39;s retries times its average failed attempt: see <a href="./flaky-tests.html#impact-ranking">Impact ranking</a>.</p><h2 id="the-run-s-timeline" tabindex="-1">The run&#39;s Timeline <a class="header-anchor" href="#the-run-s-timeline" aria-label="Permalink to &quot;The run&#39;s Timeline&quot;">​</a></h2><p>A run&#39;s <strong>Timeline</strong> tab draws each worker&#39;s tests on one time axis, with waits, locks and <a href="./editor-breakpoints.html">breakpoint</a> stops. Under the lanes it ranks the run&#39;s <strong>Slowest tests</strong>, sums each named lock&#39;s held and serialized time in <strong>Locks</strong>, and shows the <strong>Worker distribution</strong>, how the tests spread across the workers:</p><ul><li><strong>Hooks</strong>: hatched over each test&#39;s bar, setup (<code>beforeAll</code>, <code>beforeEach</code>, fixtures) at the start, teardown (<code>afterEach</code>, <code>afterAll</code>, worker cleanup) at the end. A failed hook is dark red and counted in the header, even with <strong>Show hooks</strong> off; hover it for the hooks, times and error, click it for the test&#39;s steps on that hook. Playwright leaves <code>beforeAll</code> and <code>afterAll</code> hooks and worker fixtures out of a test&#39;s duration; the bar spans them, and its tooltip gives Playwright&#39;s duration. Older reporters send no hook list.</li><li><strong>Gaps</strong>: a lane is one <a href="/reference/test-metadata.html#worker-lanes">worker</a>. Playwright replaces a worker process after a failed test, so a lane can hold several processes in turn: <strong>↻</strong> marks where a new one took over, and the stretch before it is that replacement. A dashed line is time the worker ran no test; hover either for details.</li><li><strong>Retries</strong>: a retried test has one bar per attempt, the last solid, the earlier ones pale. Hover one to join them with arrows.</li><li><strong>Resources</strong>: the run&#39;s CPU, memory and open pages, above the worker rows and under each of them.</li></ul><h2 id="time-paused-at-a-stop" tabindex="-1">Time paused at a stop <a class="header-anchor" href="#time-paused-at-a-stop" aria-label="Permalink to &quot;Time paused at a stop&quot;">​</a></h2><p>When a test stands <a href="./watch-a-run.html#where-a-test-stopped">stopped</a> at a breakpoint, a Pause or a held failure, its duration leaves the time paused out, while every step keeps its clock time: the timelines draw each stop as a <strong>Paused</strong> band, and the step statistics (the slowest step, wasted time) leave it out.</p><p>The test timeout stops while a test is paused at a breakpoint, and so does the paused call&#39;s own budget (<code>actionTimeout</code>, or <code>expect.timeout</code> for an assertion on that line). A wait the test started before the stop keeps its own deadline: <code>expect.poll</code>, <code>toPass</code>, or a <code>waitForRequest</code>, <code>waitForResponse</code> or <code>waitForEvent</code> around the paused call can run out while you look and fail the test. The pause bar then goes away, before Playwright&#39;s failure screenshot and the <code>afterEach</code> hooks.</p><h2 id="network-and-web-vitals" tabindex="-1">Network and Web Vitals <a class="header-anchor" href="#network-and-web-vitals" aria-label="Permalink to &quot;Network and Web Vitals&quot;">​</a></h2><ul><li><strong>Slow endpoints</strong> — slow API calls grouped by method and normalized route (e.g. <code>/users/:id</code>), for a run picked from the tab.</li><li><strong>Browser Web Vitals</strong> — TTFB, DOMContentLoaded, FCP and more, with color-coded thresholds, shown per execution in the <strong>Performance</strong> tab of the execution page&#39;s evidence rather than on the project.</li></ul><p>Both require the <a href="/guide/capture-fixtures.html">capture fixtures</a> in your test setup — without them the reporter has no network timings or Web Vitals to aggregate.</p><h2 id="try-it-in-the-demo" tabindex="-1">Try it in the demo <a class="header-anchor" href="#try-it-in-the-demo" aria-label="Permalink to &quot;Try it in the demo&quot;">​</a></h2>',23)),a(i),e[2]||(e[2]=o('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/recipes/faster-suite.html">Cut the time it costs</a>: the slowest tests and wasted time, cut in order of cost</li><li><a href="/guide/capture-fixtures.html">Capture fixtures</a> — the test-side setup behind network analysis and Web Vitals</li><li><a href="./flaky-tests.html">Flaky tests</a>: the time a flaky test&#39;s retries cost</li><li><a href="./analytics.html">Analytics</a>: wasted time and slow endpoints across every project</li><li><a href="/reference/test-metadata.html#per-test-timeout">Reporter</a> — how the per-test timeout is captured</li></ul>',2))])}const v=d(c,[["render",u]]);export{T as __pageData,v as default};
